struct Context{SourceFx*fx;float*l,*r;float mode;};
static void frame(SourceFx&f,const float*p,float in,float*l,float*r,float a,float b,float c,float d){std::memcpy(f.parameters.data(),p,150*4);f.frame(in,l,r,a,b,c,d);}
static void candidate(const RuntimeState&s,unsigned phase,unsigned i,void*v){if(phase!=1)return;auto&c=*static_cast<Context*>(v);if(c.mode!=s.parameters[isMono]){c.mode=s.parameters[isMono];c.fx->source_reset_delays();}frame(*c.fx,s.parameters,c.l[i],c.l+i,c.r+i,s.lfo1_0_1,s.lfo1_1_0,s.lfo2_0_1,s.lfo2_1_0);}
static void original(const OracleState&s,unsigned phase,unsigned i,void*v){if(phase!=1)return;auto&c=*static_cast<Context*>(v);if(c.mode!=s.parameters[isMono]){c.mode=s.parameters[isMono];sp_vdelay_reset(c.fx->sp,c.fx->delayL);sp_vdelay_reset(c.fx->sp,c.fx->delayR);sp_vdelay_reset(c.fx->sp,c.fx->delayRR);sp_vdelay_reset(c.fx->sp,c.fx->delayFillIn);}frame(*c.fx,s.parameters,c.l[i],c.l+i,c.r+i,s.lfo1_0_1,s.lfo1_1_0,s.lfo2_0_1,s.lfo2_1_0);}
static unsigned readu(FILE*f){unsigned v;CHECK(std::fread(&v,4,1,f)==1);return v;}
int main(int argc,char**argv){CHECK(argc==5);Fixture fixture(argv[1]);FILE*f=std::fopen(argv[2],"rb");CHECK(f);std::vector<unsigned char>pack(165292);CHECK(std::fread(pack.data(),1,pack.size(),f)==pack.size());CHECK(!std::fclose(f));compact_data=pack.data();compact_size=pack.size();f=std::fopen(argv[3],"rb");CHECK(f&&readu(f)==0x53315043);unsigned count=readu(f);unsigned long long total=0;for(unsigned k=0;k<count;++k){case_name="Actual original bank preset through source frontend/raw oracle vs compact and common originalFX";FullPair p(fixture,48000,false,false,0);s1frontend::SourceControls controls(p.s);s1frontend_oracle::OracleControls reference(p.o);SourceFx a(48000),b(48000);unsigned commands=readu(f);for(unsigned j=0;j<commands;++j){unsigned id=readu(f);float value;CHECK(std::fread(&value,4,1,f)==1);CHECK(controls.set_parameter(id,value));CHECK(reference.set_parameter(id,value));p.compare();}p.reset_seq();Context ca{&a,nullptr,nullptr,0},cb{&b,nullptr,nullptr,0};char fn[512];std::snprintf(fn,sizeof fn,"%s/preset-%02u-original.f32le.pcm",argv[4],k);FILE*oa=std::fopen(fn,"wb");std::snprintf(fn,sizeof fn,"%s/preset-%02u-compact.f32le.pcm",argv[4],k);FILE*ob=std::fopen(fn,"wb");CHECK(oa&&ob);double energy=0;float peak=0;unsigned at=0;for(unsigned step=0;at<96000;++step){if(at%12000==0){p.stop_all();if(at<72000){int note[]={48,55,60,64,67,72};p.start(note[(at/12000)%6],64+int(at/12000)*11);}}unsigned n=std::min(128u,96000-at);if(at%12000+n>12000)n=12000-at%12000;float sl[128]{},sr[128]{},ol[128]{},orr[128]{};ca.l=sl;ca.r=sr;cb.l=ol;cb.r=orr;p.s.trace_fn=candidate;p.s.trace_context=&ca;p.o.trace_fn=original;p.o.trace_context=&cb;compact_oracle_window=true;p.o.process(n,0,ol,orr);compact_oracle_window=false;{NoHeap guard;CHECK(p.s.process(n,0,sl,sr));}p.s.trace_fn=nullptr;p.o.trace_fn=nullptr;CHECK(!memcmp(sl,ol,n*4)&&!memcmp(sr,orr,n*4));for(unsigned i=0;i<n;++i){CHECK(std::isfinite(sl[i])&&std::isfinite(sr[i]));float x[]={ol[i],orr[i]},y[]={sl[i],sr[i]};CHECK(fwrite(x,4,2,oa)==2&&fwrite(y,4,2,ob)==2);energy+=double(sl[i])*sl[i]+double(sr[i])*sr[i];peak=std::max(peak,std::max(std::fabs(sl[i]),std::fabs(sr[i])));}at+=n;total+=n;p.compare();}CHECK(!fclose(oa)&&!fclose(ob));std::printf("{\"preset_index\":%u,\"commands\":%u,\"frames\":96000,\"paired_bitexact\":true,\"peak\":%.9g,\"energy\":%.17g}\n",k,commands,peak,energy);fflush(stdout);std::snprintf(fn,sizeof fn,"%s/progress.json",argv[4]);FILE*progress=std::fopen(fn,"w");CHECK(progress);std::fprintf(progress,"{\"completed_presets\":%u,\"total_presets\":%u,\"frames\":%llu}\n",k+1,count,total);CHECK(!fclose(progress));}CHECK(!fclose(f));std::printf("{\"actual_original_presets\":%u,\"frames\":%llu,\"paired_bitexact\":true,\"scope\":\"Source helper laws + real original preset scalar/seq bindings/raw oracle vs compact/common originalFX; not Apple UI, complete tuning/hold/modwheel or target fidelity\"}\n",count,total);}
